from modele import chapitre,E,Q,tableau

chapitre(10,'statistiques','Moyenne, médiane et étendue','3 · Données et hasard',
'Moyenne pondérée · Médiane · Étendue · Tableur',
['Calculer une moyenne pondérée à partir de données, d’un tableau ou d’un diagramme.','Déterminer et interpréter une médiane et une étendue.','Comparer des séries et utiliser un tableur.'],
['Effectifs, fréquences, moyenne simple et diagrammes (Cinquième).'],[
r'''\essSection{1}{Effectifs et moyenne pondérée}
\begin{definition}L’effectif d’une valeur est le nombre de fois où elle apparaît ; l’effectif total est la somme des effectifs. La fréquence d’une valeur est son effectif divisé par l’effectif total ; les fréquences de toutes les valeurs ont pour somme 1.\end{definition}
\begin{propriete}La moyenne d’une série est la somme de toutes ses valeurs divisée par l’effectif total. Quand les valeurs ont des effectifs, on additionne les produits valeur $\times$ effectif : on calcule une moyenne pondérée par les effectifs.\end{propriete}
\begin{exemple}Valeurs 2, 5 et 8 d’effectifs 4, 3 et 3 : $\frac{2\times4+5\times3+8\times3}{4+3+3}=\frac{47}{10}=4{,}7$. Une moyenne n’est pas forcément une valeur de la série, ni un nombre entier.\end{exemple}
\begin{savoirfaire}[Organiser avant de calculer]Pour une longue liste de données brutes, construire d’abord un tableau d’effectifs. Garder les unités dans les calculs : 126 livres lus par 30 élèves donnent $\frac{126\text{ livres}}{30\text{ élèves}}=4{,}2$ livres par élève en moyenne.\end{savoirfaire}
\begin{attention}On ne calcule pas la moyenne des seules valeurs 2, 5 et 8 sans tenir compte de leurs effectifs. Pour comparer deux groupes de tailles différentes, on compare des fréquences ou des moyennes, pas des totaux.\end{attention}''',
r'''\essSection{2}{Médiane et étendue}
\begin{definition}Une médiane d’une série est une valeur qui partage la série ordonnée en deux parties de même effectif. Pour un effectif impair, c’est la valeur centrale. Pour un effectif pair, toute valeur comprise entre les deux valeurs centrales convient ; on choisit souvent leur moyenne.\end{definition}
\begin{definition}L’étendue d’une série est la différence entre sa plus grande et sa plus petite valeur. Elle renseigne sur la dispersion des valeurs.\end{definition}
\begin{exemple}Pour 2, 4, 4, 7, 8 : la médiane est la 3e valeur, 4, et l’étendue vaut $8-2=6$. Pour 2, 4, 7, 9 : toute valeur comprise entre 4 et 7 est une médiane, par exemple 5,5 ; deux valeurs sont en dessous et deux au-dessus.\end{exemple}
\begin{propriete}[Valeur extrême]Ajouter ou modifier une valeur très grande ou très petite change fortement la moyenne et l’étendue, mais peu la médiane : celle-ci dépend du rang des valeurs, pas de leur taille.\end{propriete}
\begin{savoirfaire}[Avec un tableur]Pour des valeurs saisies dans les cellules A2 à A31, on obtient la moyenne avec \texttt{=MOYENNE(A2:A31)}, une médiane avec \texttt{=MEDIANE(A2:A31)}, l’étendue avec \texttt{=MAX(A2:A31)-MIN(A2:A31)} et l’effectif total avec \texttt{=NB(A2:A31)}.\end{savoirfaire}'''],[
E('Un effectif total',r"Les notes 8, 10 et 12 ont respectivement pour effectifs 3, 5 et 2. Donner l’effectif total et la fréquence de la note 10.",r"Le total vaut $3+5+2=\res{10}$. La fréquence de 10 est $\frac5{10}=\res{0{,}5}$, soit 50\,\%.","Additionner les effectifs avant de calculer la fréquence.","assert 3+5+2==10 and Rational(5,10)==Rational(1,2)"),
E('Une moyenne simple',r"Calculer la moyenne de 6, 9, 10 et 15.",r"La somme vaut $6+9+10+15=40$. On divise par quatre valeurs : $40:4=\res{10}$.","Additionner toutes les valeurs et compter les données.","assert Rational(6+9+10+15,4)==10"),
E('Une médiane impaire',r"Déterminer la médiane de la série : 12, 7, 9, 15, 8.",r"La série rangée est 7, 8, 9, 12, 15. L’effectif est 5 : la 3e valeur est centrale. La médiane vaut $\res9$ : deux valeurs sont plus petites et deux plus grandes.","Ranger avant de chercher le rang central.","assert sorted([12,7,9,15,8])[2]==9"),
E('Deux étendues',r"Donner l’étendue de la série 12, 7, 9, 15, 8, puis celle de la série $-3$, 4, 2, $-6$.",r"Première série : $15-7=\res8$. Seconde série : $4-(-6)=\res{10}$. On soustrait toujours la plus petite valeur à la plus grande.","Repérer le maximum et le minimum.","assert max([12,7,9,15,8])-min([12,7,9,15,8])==8 and max([-3,4,2,-6])-min([-3,4,2,-6])==10"),
E('Un effectif manquant',r"Une série de 25 notes est donnée par le tableau ci-dessous. Retrouver l’effectif manquant et la fréquence de la note 10."+tableau(['Note','8','10','12','15'],[['Effectif','4','?','9','5']]),r"L’effectif manquant vaut $25-(4+9+5)=\res7$. La fréquence de la note 10 est $\frac7{25}=\res{0{,}28}$, soit 28\,\%.","Utiliser l’effectif total.","assert 25-(4+9+5)==7 and Rational(7,25)==Rational('0.28')"),
E('Une moyenne pondérée',r"Les valeurs 1, 4 et 6 ont pour effectifs 5, 2 et 3. Calculer la moyenne de la série.",r"L’effectif total vaut 10. La somme pondérée est $1\times5+4\times2+6\times3=31$. La moyenne est $\frac{31}{10}=\res{3{,}1}$. Moyenner seulement 1, 4 et 6 donnerait $3{,}67$ environ : un résultat faux.","Tenir compte des répétitions.","assert Rational(1*5+4*2+6*3,10)==Rational('3.1')"),
E('Lire un diagramme en bâtons',r"Le diagramme donne le nombre de livres lus par 12 élèves pendant les vacances. Calculer la moyenne, une médiane et l’étendue.",r"Les effectifs sont 2, 4, 3, 2 et 1 pour 0, 1, 2, 3 et 4 livres. Moyenne : $\frac{0+4+6+6+4}{12}=\frac{20}{12}\approx\res{1{,}67}$ livre. Les 6e et 7e valeurs sont 1 et 2 : toute valeur entre 1 et 2 est une médiane, par exemple $\res{1{,}5}$. Étendue : $4-0=\res4$ livres.","Retrouver les rangs à partir des effectifs.","assert Rational(0*2+1*4+2*3+3*2+4*1,12)==Rational(5,3) and sorted([0]*2+[1]*4+[2]*3+[3]*2+[4])[5:7]==[1,2]",figure='stat-livres'),
E('Une médiane paire',r"Déterminer une médiane de la série : 3, 4, 8, 10, 12, 15.",r"Il y a six valeurs, déjà rangées. Les valeurs centrales sont aux rangs 3 et 4 : 8 et 10. Toute valeur comprise entre 8 et 10 est une médiane ; on choisit leur moyenne, $\res9$. Trois valeurs sont inférieures à 9 et trois supérieures.","Repérer les deux rangs centraux.","assert Rational(8+10,2)==9 and len([a for a in [3,4,8,10,12,15] if a<9])==3"),
E('Un diagramme circulaire',r"Le diagramme circulaire donne la répartition des 40 élèves d’un niveau selon leur nombre de frères et sœurs. Calculer l’étendue, puis l’effectif de chaque valeur et la moyenne.",r"Les valeurs vont de 0 à 5 : l’étendue vaut $\res5$. Un angle de $90^\circ$ représente $\frac{90}{360}=\frac14$ des élèves, soit 10 élèves. Les effectifs sont $\res{10,\ 16,\ 8,\ 4,\ 2}$ pour 0, 1, 2, 3 et 5. Moyenne : $\frac{0+16+16+12+10}{40}=\frac{54}{40}=\res{1{,}35}$.","Passer de l’angle à l’effectif.","assert [Rational(a,360)*40 for a in [90,144,72,36,18]]==[10,16,8,4,2] and Rational(0*10+1*16+2*8+3*4+5*2,40)==Rational('1.35')",figure='stat-fratrie'),
E('Des formules de tableur',r"Les durées de trajet de dix élèves, en minutes, sont saisies en A2:A11 : 12, 15, 9, 20, 15, 11, 18, 15, 30, 10. Écrire les formules donnant la moyenne, la médiane, l’étendue et l’effectif, puis les résultats affichés.",r"\texttt{=MOYENNE(A2:A11)} affiche $\res{15{,}5}$ ; \texttt{=MEDIANE(A2:A11)} affiche $\res{15}$ ; \texttt{=MAX(A2:A11)-MIN(A2:A11)} affiche $30-9=\res{21}$ ; \texttt{=NB(A2:A11)} affiche $\res{10}$. Les valeurs rangées ont pour 5e et 6e valeurs 15 et 15.","Associer chaque indicateur à sa fonction.","d=[12,15,9,20,15,11,18,15,30,10]; s=sorted(d); assert Rational(sum(d),len(d))==Rational('15.5') and Rational(s[4]+s[5],2)==15 and max(d)-min(d)==21 and len(d)==10"),
E('Ajouter une valeur',r"Cinq élèves ont une moyenne de 12 points à un jeu. Un sixième élève rejoint le groupe avec 18 points. Quelle est la nouvelle moyenne ?",r"La somme initiale vaut $5\times12=60$. La nouvelle somme vaut $60+18=78$, pour 6 élèves. La moyenne est $78:6=\res{13}$. Moyenner 12 et 18 donnerait un mauvais poids aux cinq premiers élèves.","Retrouver la somme à partir de la moyenne.","assert Rational(5*12+18,6)==13"),
E('Une valeur manquante',r"Les nombres 8, 11, 14 et $x$ ont une moyenne de 12. Trouver $x$, puis une médiane de la série.",r"La somme doit valoir $4\times12=48$. Donc $x=48-(8+11+14)=\res{15}$. La série rangée est 8, 11, 14, 15 : toute valeur entre 11 et 14 est une médiane, par exemple $\res{12{,}5}$.","Utiliser la moyenne pour retrouver le total.","assert 4*12-(8+11+14)==15 and Rational(11+14,2)==Rational('12.5')"),
E('Une valeur extrême',r"Comparer moyenne, médiane et étendue des séries A : 4, 5, 6, 7, 8 et B : 4, 5, 6, 7, 38.",r"Pour A : moyenne 6, médiane 6, étendue 4. Pour B, la somme vaut 60 : moyenne $\res{12}$, médiane toujours $\res6$, étendue $\res{34}$. Modifier la seule plus grande valeur change fortement la moyenne et l’étendue, pas la médiane.","Calculer séparément les trois indicateurs.","assert sum([4,5,6,7,8])/5==6 and sum([4,5,6,7,38])/5==12 and sorted([4,5,6,7,38])[2]==6 and 38-4==34"),
E('Comparer deux classes',r"Nombre de livres empruntés dans l’année. Classe A, 10 élèves : 0, 1, 1, 2, 2, 2, 3, 5, 6, 8. Classe B : effectif 12, moyenne 3,5 livres, médiane 4 livres, étendue 6 livres."+Q(r"Quelle classe a la plus grande moyenne ?",r"Un « grand lecteur » emprunte au moins 4 livres. Quelle classe en compte le plus ?",r"Dans quelle classe les nombres de livres sont-ils les plus dispersés ?"),r"La classe A a une moyenne de $\frac{30}{10}=3$ livres : $\res{B}$ a la plus grande moyenne. Dans A, trois élèves empruntent au moins 4 livres. Dans B, la médiane 4 montre qu’au moins 6 élèves sur 12 empruntent au moins 4 livres : $\res{B}$ en compte le plus. L’étendue de A vaut 8, celle de B 6 : les valeurs de $\res{A}$ sont les plus dispersées.","Utiliser le sens de chaque indicateur.","a=[0,1,1,2,2,2,3,5,6,8]; assert Rational(sum(a),10)==3<Rational('3.5') and len([v for v in a if v>=4])==3<6 and max(a)-min(a)==8>6"),
E('Interpréter une médiane',r"Dans une série de 20 durées, une médiane vaut 15 min. Peut-on conclure que dix durées valent exactement 15 min ? Donner un exemple qui justifie la réponse.",r"Non : une médiane parle de position dans la série ordonnée, pas du nombre de valeurs égales à 15. Par exemple, dix durées de 10 min et dix de 20 min : toute valeur entre 10 et 20 est une médiane, donc 15 aussi, alors $\res{\text{aucune durée ne vaut 15 min}}$.","Distinguer valeur centrale et effectif d’une valeur.","d=[10]*10+[20]*10; assert len([v for v in d if v<15])==len([v for v in d if v>15])==10 and 15 not in d")
],reperes=['Effectifs, fréquences et moyenne pondérée','Médiane d’une série de petit effectif','Étendue et valeurs extrêmes','Comparaison de séries et tableur'],deco='statistiques')

chapitre(11,'probabilites','Probabilités : événements et deux épreuves','3 · Données et hasard',
'Univers · Contraire · Réunion · Intersection · Fréquences',
['Décrire une expérience aléatoire avec le vocabulaire et les notations des ensembles.','Calculer la probabilité d’un événement et de son contraire.','Étudier une expérience à deux épreuves et observer la fluctuation des fréquences.'],
['Vocabulaire des probabilités et équiprobabilité (Cinquième), fractions.'],[
r'''\essSection{1}{Issues, événements et ensembles}
\begin{definition}Une expérience aléatoire a plusieurs résultats possibles, les issues, sans que l’on puisse prévoir lequel se produira. L’ensemble de toutes les issues est l’univers : pour un dé à six faces, $\{1\,;2\,;3\,;4\,;5\,;6\}$. Un événement est un ensemble d’issues, par exemple $A=\{3\,;6\}$, « obtenir un multiple de 3 ».\end{definition}
\begin{definition}[Opérations sur les événements]Le contraire de $A$, noté $\overline{A}$, contient les issues qui ne sont pas dans $A$ : c’est son complémentaire. L’intersection $A\cap B$, « $A$ et $B$ », contient les issues communes. La réunion $A\cup B$, « $A$ ou $B$ », contient les issues d’au moins un des deux événements. L’ensemble vide, noté $\varnothing$, est l’événement impossible.\end{definition}
\begin{propriete}La probabilité $P(A)$ d’un événement est un nombre compris entre 0 et 1 : c’est la somme des probabilités des issues qui le composent. Si les issues sont équiprobables, $P(A)$ est le nombre d’issues de $A$ divisé par le nombre total d’issues. Enfin $P(\overline A)=1-P(A)$.\end{propriete}
\begin{exemple}Dé équilibré, $A=\{3\,;6\}$ et $B=\{2\,;4\,;6\}$ : $A\cap B=\{6\}$, $A\cup B=\{2\,;3\,;4\,;6\}$ et $\overline A=\{1\,;2\,;4\,;5\}$. Donc $P(A\cup B)=\frac46=\frac23$ et $P(\overline A)=1-\frac26=\frac23$.\end{exemple}''',
r'''\essSection{2}{Deux épreuves et fréquences}
\begin{savoirfaire}[Lister les issues]Pour une expérience à deux épreuves, on liste les couples d’issues avec un arbre ou un tableau à double entrée. Une pièce puis un dé donnent $2\times6=12$ issues, de $(P\,;1)$ à $(F\,;6)$ ; avec une pièce et un dé équilibrés, on choisit l’équiprobabilité de ces 12 issues.\end{savoirfaire}
@FIG:cours-arbre-pieces@
\begin{exemple}Deux pièces équilibrées que l’on distingue : les quatre issues $PP$, $PF$, $FP$, $FF$ sont équiprobables. « Obtenir une pile et une face » contient $PF$ et $FP$ : sa probabilité vaut $\frac24=\frac12$, et non $\frac13$.\end{exemple}
\begin{definition}[Fréquences observées]Quand on répète une expérience, la fréquence d’une issue est son effectif divisé par le nombre de répétitions. Pour un même nombre de répétitions, les fréquences varient d’une série à l’autre : c’est la fluctuation. Une fréquence observée fournit une approximation de la probabilité.\end{definition}
\begin{attention}On distingue la situation réelle du modèle choisi pour la décrire : l’équiprobabilité se justifie par la symétrie d’une pièce ou d’un dé, pas par un résultat observé. Pour deux dés lancés ensemble, on les distingue, par exemple par leurs couleurs.\end{attention}'''],[
E('Décrire un univers',r"On lance un dé équilibré à huit faces numérotées de 1 à 8. Écrire l’univers, puis l’événement $A$ : « obtenir un multiple de 3 ». Calculer $P(A)$.",r"L’univers est $\res{\{1\,;2\,;3\,;4\,;5\,;6\,;7\,;8\}}$. Les multiples de 3 sont 3 et 6 : $A=\res{\{3\,;6\}}$. Les huit issues sont équiprobables, donc $P(A)=\frac28=\res{\frac14}$.","Écrire les issues avant de compter.","assert [a for a in range(1,9) if a%3==0]==[3,6] and Rational(2,8)==Rational(1,4)"),
E('L’événement contraire',r"Avec le même dé à huit faces, écrire $\overline{A}$ et calculer sa probabilité de deux façons.",r"$\overline A$ contient les issues qui ne sont pas dans $A$ : $\res{\{1\,;2\,;4\,;5\,;7\,;8\}}$. Par comptage, $P(\overline A)=\frac68=\frac34$. Par le contraire, $1-\frac14=\res{\frac34}$.","Prendre le complémentaire dans l’univers.","assert [a for a in range(1,9) if a%3]==[1,2,4,5,7,8] and 1-Rational(1,4)==Rational(6,8)"),
E('Certain et impossible',r"On lance un dé classique à six faces. Donner un événement certain, puis un événement égal à l’ensemble vide, avec leurs probabilités.",r"« Obtenir un nombre inférieur à 7 » contient toutes les issues : il est certain, de probabilité $\res1$. « Obtenir 8 » ne contient aucune issue : c’est $\varnothing$, l’événement impossible, de probabilité $\res0$.","Comparer l’événement à l’univers.","assert all(a<7 for a in range(1,7)) and 8 not in range(1,7)"),
E('Plusieurs écritures',r"Une probabilité vaut $\frac38$. L’écrire sous forme décimale et en pourcentage.",r"$\frac38=\res{0{,}375}$, soit $\res{37{,}5\,\%}$. Les trois écritures représentent la même probabilité.","Passer de la fraction au quotient puis au pourcentage.","assert Rational(3,8)==Rational('.375') and Rational(3,8)*100==Rational('37.5')"),
E('Une urne',r"Une urne contient 4 boules rouges, 3 bleues et 1 verte, indiscernables au toucher. On tire une boule au hasard. On note $R$ l’événement « obtenir une boule rouge ». Calculer $P(R)$ et $P(\overline R)$.",r"Les 8 boules ont la même chance d’être tirées. $P(R)=\frac48=\res{\frac12}$. $\overline R$ contient les 3 bleues et la verte : $P(\overline R)=\frac48=\res{\frac12}$. Compter trois couleurs ne donnerait pas trois chances égales.","Compter les objets équiprobables.","assert Rational(4,8)==Rational(3+1,8)==Rational(1,2)",figure='urne-431'),
E('Intersection et réunion',r"On lance un dé équilibré à six faces. $A$ : « obtenir un nombre pair » ; $B$ : « obtenir au moins 4 ». Écrire $A$, $B$, $A\cap B$ et $A\cup B$, puis calculer leurs probabilités.",r"$A=\{2\,;4\,;6\}$ et $B=\{4\,;5\,;6\}$, de probabilité $\frac12$ chacun. $A\cap B=\res{\{4\,;6\}}$ : probabilité $\res{\frac13}$. $A\cup B=\res{\{2\,;4\,;5\,;6\}}$ : probabilité $\frac46=\res{\frac23}$. Les issues 4 et 6, communes, ne sont comptées qu’une fois dans la réunion.","Placer chaque issue dans le bon ensemble.","A={2,4,6}; B={4,5,6}; assert A&B=={4,6} and A|B=={2,4,5,6} and Rational(len(A|B),6)==Rational(2,3)",figure='venn-de'),
E('Deux pièces',r"On lance une pièce de 1 euro et une pièce de 2 euros, toutes deux équilibrées. Construire un arbre, donner les issues et calculer la probabilité d’obtenir une pile et une face.",r"L’arbre donne quatre issues équiprobables : $(P\,;P)$, $(P\,;F)$, $(F\,;P)$ et $(F\,;F)$. L’événement contient $(P\,;F)$ et $(F\,;P)$ : sa probabilité vaut $\frac24=\res{\frac12}$. Les deux pièces sont distinguées, donc $PF$ et $FP$ sont deux issues différentes.","Distinguer les deux épreuves.","issues=[(a,b) for a in 'PF' for b in 'PF']; assert len(issues)==4 and Rational(len([i for i in issues if i[0]!=i[1]]),4)==Rational(1,2)",figure='arbre-deux-pieces'),
E('Une pièce et un dé',r"On lance une pièce équilibrée puis un dé équilibré à six faces. Combien y a-t-il d’issues ? Calculer la probabilité de « pile et un nombre pair », puis celle de « face ou 6 ».",r"Le tableau compte $2\times6=\res{12}$ issues équiprobables. « Pile et pair » contient $(P\,;2)$, $(P\,;4)$ et $(P\,;6)$ : probabilité $\frac3{12}=\res{\frac14}$. « Face ou 6 » contient les six issues avec face et $(P\,;6)$ : probabilité $\res{\frac7{12}}$.","Repérer les cases du tableau qui conviennent.","U=[(a,b) for a in 'PF' for b in range(1,7)]; assert len(U)==12 and Rational(len([u for u in U if u[0]=='P' and u[1]%2==0]),12)==Rational(1,4) and Rational(len([u for u in U if u[0]=='F' or u[1]==6]),12)==Rational(7,12)",figure='tableau-piece-de'),
E('La somme de deux dés',r"On lance un dé rouge et un dé bleu, équilibrés, et l’on additionne les deux nombres. Compléter le tableau des sommes. Calculer la probabilité d’obtenir 7, puis celle d’obtenir au moins 10.",r"Le tableau contient 36 issues équiprobables. La somme 7 apparaît 6 fois : probabilité $\frac6{36}=\res{\frac16}$. Les sommes 10, 11 et 12 apparaissent $3+2+1=6$ fois : probabilité $\res{\frac16}$ aussi.","Compter les cases du tableau à double entrée.","S=[a+b for a in range(1,7) for b in range(1,7)]; assert S.count(7)==6 and len([s for s in S if s>=10])==6",figure='somme-deux-des'),
E('Des issues non équiprobables',r"Un objet lancé a trois issues A, B, C de probabilités respectives 0,2 ; 0,5 et $p$. Trouver $p$, puis la probabilité de ne pas obtenir B.",r"Le total des trois probabilités vaut 1, donc $p=1-0{,}2-0{,}5=\res{0{,}3}$. La probabilité de ne pas obtenir B est $1-0{,}5=\res{0{,}5}$. On ne compte pas simplement un tiers par issue.","Utiliser la somme des probabilités des issues.","assert 1-Rational('.2')-Rational('.5')==Rational('.3')"),
E('Une observation',r"Sur 50 lancers d’une pièce équilibrée, on observe 31 piles. Calculer la fréquence observée. Doit-on dire que la probabilité du prochain pile vaut $\frac{31}{50}$ ?",r"La fréquence observée est $\frac{31}{50}=\res{0{,}62}$. Le modèle reste une probabilité de pile égale à $\res{\frac12}$ pour le prochain lancer. Sur un nombre fini de lancers, la fréquence peut s’écarter de la probabilité.","Séparer observation et modèle.","assert Rational(31,50)==Rational('.62') and Rational(31,50)!=Rational(1,2)"),
E('Quatre séries de lancers',r"Quatre groupes lancent chacun 50 fois une pièce équilibrée et obtiennent 23, 28, 25 et 31 piles. Calculer les quatre fréquences de pile. Pourquoi sont-elles différentes ? Calculer la fréquence sur les 200 lancers réunis.",r"Les fréquences sont $\res{0{,}46}$, $\res{0{,}56}$, $\res{0{,}50}$ et $\res{0{,}62}$. Pour un même nombre de lancers, le hasard fait varier les résultats : c’est la fluctuation. Sur les 200 lancers, $\frac{107}{200}=\res{0{,}535}$, proche de la probabilité 0,5.","Diviser chaque effectif par le nombre de lancers.","f=[Rational(a,50) for a in [23,28,25,31]]; assert f==[Rational('0.46'),Rational('0.56'),Rational('0.5'),Rational('0.62')] and Rational(23+28+25+31,200)==Rational('0.535')",figure='fluctuation-pieces'),
E('Fréquences et probabilités',r"On lance 60 fois deux pièces équilibrées et l’on compte les piles : 0 pile 13 fois, 1 pile 32 fois, 2 piles 15 fois. Calculer les fréquences au centième, puis compléter le diagramme en les comparant aux probabilités du modèle.",r"Fréquences : $\frac{13}{60}\approx\res{0{,}22}$, $\frac{32}{60}\approx\res{0{,}53}$ et $\frac{15}{60}=\res{0{,}25}$. Le modèle des quatre issues équiprobables donne $\frac14$, $\frac12$ et $\frac14$. Les fréquences en sont proches sans leur être égales : les deux diagrammes ont la même allure.","Associer chaque nombre de piles à ses issues.","assert [round(a/60,2) for a in [13,32,15]]==[0.22,0.53,0.25] and [Rational(c,4) for c in [1,2,1]]==[Rational(1,4),Rational(1,2),Rational(1,4)]",figure='distribution-deux-pieces'),
E('Un effectif inconnu',r"Un sac contient 5 boules rouges et un nombre $b$ de boules bleues, indiscernables au toucher. La probabilité de tirer une boule rouge vaut $\frac14$. Trouver $b$.",r"Les rouges représentent un quart du total, donc le sac contient $5\times4=20$ boules. Les bleues sont $20-5=\res{15}$. Contrôle : $\frac5{5+15}=\frac14$.","Retrouver le total à partir de la part rouge.","assert Rational(5,5+15)==Rational(1,4)"),
E('Des numéros et des couleurs',r"Un sac contient six jetons équiprobables : R1, R2, R3, B1, B2 et V1. $R$ : « le jeton est rouge » ; $U$ : « le jeton porte le numéro 1 ». Écrire $R\cap U$ et $R\cup U$, puis calculer $P(R\cup U)$. Pourquoi n’est-elle pas égale à $P(R)+P(U)$ ?",r"$R\cap U=\res{\{R1\}}$ et $R\cup U=\res{\{R1\,;R2\,;R3\,;B1\,;V1\}}$, donc $P(R\cup U)=\res{\frac56}$. Or $P(R)+P(U)=\frac36+\frac36=1$ : le jeton R1, qui appartient aux deux événements, serait compté deux fois.","Énumérer les issues favorables sans répétition.","R={'R1','R2','R3'}; U={'R1','B1','V1'}; assert R&U=={'R1'} and Rational(len(R|U),6)==Rational(5,6) and Rational(3,6)+Rational(3,6)==1",figure='jetons-numerotes')
],reperes=['Univers, événements et notations','Contraire, réunion et intersection','Expériences à deux épreuves','Fréquences et fluctuation'],deco='probabilites')

chapitre(12,'raisonnement','Droites remarquables et raisonnement','4 · Géométrie et espace',
'Médiatrices · Hauteurs · Médianes · Réciproque · Contraposée',
['Reconnaître les droites remarquables d’un triangle et utiliser leurs propriétés.','Distinguer hypothèse, conclusion, réciproque et contraposée.','Démontrer par déduction, par un contre-exemple ou par l’absurde.'],
['Médiatrice, hauteurs, médianes, angles et parallélogrammes (Cinquième).'],[
r'''\essSection{1}{Les droites remarquables}
\begin{definition}Dans un triangle, la médiatrice d’un côté est la droite perpendiculaire à ce côté en son milieu. Une hauteur passe par un sommet et est perpendiculaire à la droite qui porte le côté opposé. Une médiane passe par un sommet et par le milieu du côté opposé. La bissectrice d’un angle le partage en deux angles de même mesure.\end{definition}
@FIG:cours-droites-remarquables@
\begin{propriete}[Rappels de Cinquième]Un point appartient à la médiatrice de $[AB]$ si et seulement s’il est équidistant de A et de B. Les trois médiatrices d’un triangle sont concourantes au centre de son cercle circonscrit ; les trois hauteurs sont concourantes, ainsi que les trois médianes. Une médiane partage le triangle en deux triangles de même aire.\end{propriete}
\begin{exemple}Dans un triangle ABC isocèle en A, la médiatrice de $[BC]$ passe par A, car $AB=AC$. Elle porte donc la médiane et la hauteur issues de A, et c’est la bissectrice de l’angle en A : elle est l’axe de symétrie du triangle.\end{exemple}''',
r'''\essSection{2}{Démontrer et raisonner}
\begin{definition}Un énoncé « Si P, alors Q » a une hypothèse P et une conclusion Q. Sa réciproque est l’énoncé « Si Q, alors P ». Sa contraposée est l’énoncé « Si Q est faux, alors P est faux ». Un énoncé démontré s’appelle un théorème.\end{definition}
\begin{propriete}Si un énoncé est vrai, sa contraposée est vraie aussi ; sa réciproque peut être vraie ou fausse. Lorsqu’un énoncé et sa réciproque sont vrais, on obtient une propriété caractéristique : « M est sur la médiatrice de $[AB]$ si et seulement si $MA=MB$ ».\end{propriete}
\begin{exemple}« Si ABCD est un rectangle, alors ses diagonales ont la même longueur » est vrai. Sa réciproque est fausse : un trapèze isocèle a des diagonales de même longueur. Sa contraposée est vraie : si les diagonales ont des longueurs différentes, ABCD n’est pas un rectangle.\end{exemple}
\begin{savoirfaire}[Trois façons de raisonner]Déduire : enchaîner les données, une propriété citée et la conclusion. Réfuter : un seul contre-exemple montre qu’un énoncé général est faux. Raisonner par l’absurde : supposer le contraire de ce que l’on veut prouver et aboutir à une contradiction.\end{savoirfaire}
\begin{attention}Une mesure sur un dessin, ou quelques exemples qui marchent, ne prouvent pas une propriété générale. On précise si une propriété utilisée est admise ou démontrée.\end{attention}'''],[
E('Reconnaître des droites',r"Sur la figure codée, nommer la nature des droites $(d_1)$, $(d_2)$ et $(d_3)$ dans le triangle ABC, en justifiant par le codage.",r"$(d_1)$ est perpendiculaire à $[BC]$ en son milieu I : c’est la $\res{\text{médiatrice de }[BC]}$. $(d_2)$ passe par C et est perpendiculaire à $(AB)$ : c’est la $\res{\text{hauteur issue de C}}$. $(d_3)$ passe par B et par le milieu J de $[AC]$ : c’est la $\res{\text{médiane issue de B}}$.","Lire chaque codage : angle droit, milieu, sommet.","A=(2,4); B=(0,0); C=(7,0); H=(Rational(7,5),Rational(14,5)); I=(Rational(7,2),0); J=(Rational(9,2),2); assert (C[0]-H[0])*(A[0]-B[0])+(C[1]-H[1])*(A[1]-B[1])==0 and H[1]==2*H[0] and 2*I[0]==B[0]+C[0] and (2*J[0],2*J[1])==(A[0]+C[0],A[1]+C[1])",figure='rem-01'),
E('Hypothèse et conclusion',r"Énoncé : « Si ABCD est un rectangle, alors ses diagonales ont la même longueur. » Donner l’hypothèse et la conclusion, puis écrire la réciproque. Est-elle vraie ?",r"Hypothèse : ABCD est un rectangle. Conclusion : $AC=BD$. Réciproque : « Si un quadrilatère a des diagonales de même longueur, alors c’est un rectangle. » Elle est $\res{\text{fausse}}$ : le trapèze isocèle EFGH de la figure corrigée a des diagonales de même longueur sans être un rectangle.","Échanger hypothèse et conclusion pour la réciproque.","E_=(0,0);F=(6,0);G=(4.5,3);H=(1.5,3); assert (G[0]-E_[0])**2+(G[1]-E_[1])**2==(H[0]-F[0])**2+(H[1]-F[1])**2 and (F[0]-E_[0])*(H[0]-E_[0])+(F[1]-E_[1])*(H[1]-E_[1])!=0",figure='rem-02'),
E('Une hauteur et une aire',r"Dans le triangle ABC, $AB=8$ cm et la hauteur issue de C mesure $CH=3$ cm. Calculer l’aire du triangle. Pourquoi ne peut-on pas utiliser AC à la place de CH ?",r"$\mathcal A=\frac{AB\times CH}2=\frac{8\times3}2=\res{12\ \mathrm{cm}^2}$. La hauteur CH est perpendiculaire à la droite $(AB)$ qui porte la base ; le côté AC ne l’est pas nécessairement.","Associer une base à la hauteur perpendiculaire.","assert Rational(8*3,2)==12",figure='rem-03'),
E('Un point de la médiatrice',r"Le point M appartient à la médiatrice de $[AB]$ et $MA=4{,}5$ cm. Que vaut MB ? Un point N vérifie $NA=NB=6$ cm : à quelle droite appartient-il ?",r"M est sur la médiatrice, donc il est équidistant de A et B : $\res{MB=4{,}5\ \mathrm{cm}}$. N est équidistant de A et B, donc il appartient à la $\res{\text{médiatrice de }[AB]}$ : on utilise ici la réciproque, vraie elle aussi.","Utiliser la propriété caractéristique dans les deux sens.","assert Rational('4.5')==Rational('4.5') and 6==6",figure='rem-04'),
E('Les angles d’un triangle isocèle',r"ABC est isocèle en A, avec $AB=AC$ et $\widehat{BAC}=74^\circ$. Déterminer les deux autres angles.",r"Les angles à la base, en B et en C, sont égaux. Leur somme vaut $180-74=106^\circ$ ; chacun vaut $106:2=\res{53^\circ}$. On utilise la somme des angles d’un triangle et la symétrie du triangle isocèle.","Répartir la somme restante en deux angles égaux.","assert Rational(180-74,2)==53",figure='rem-05'),
E('Un contre-exemple',r"Léo affirme : « Deux triangles qui ont la même aire ont les mêmes longueurs de côtés. » Montrer qu’il a tort.",r"Il suffit d’un contre-exemple. Le triangle rectangle de côtés de l’angle droit 4 cm et 3 cm a pour aire $\frac{4\times3}2=6$ cm$^2$. Le triangle de base 6 cm et de hauteur 2 cm a aussi pour aire $\frac{6\times2}2=6$ cm$^2$, mais une base de 6 cm, plus longue que tous les côtés du premier, dont le plus long mesure 5 cm. L’affirmation est $\res{\text{fausse}}$.","Construire deux triangles de même aire et de côtés différents.","assert Rational(4*3,2)==Rational(6*2,2)==6 and sqrt(4**2+3**2)==5<6",figure='rem-06'),
E('Une médiane partage l’aire',r"Dans le triangle ABC, I est le milieu de $[BC]$ et H le pied de la hauteur issue de A. L’aire de ABC vaut 30 cm$^2$. Démontrer que ABI et AIC ont la même aire, puis la calculer.",r"Les triangles ABI et AIC ont des bases de même longueur, $BI=IC$, car I est le milieu de $[BC]$. Ils ont la même hauteur AH, perpendiculaire à $(BC)$. Leurs aires $\frac{BI\times AH}2$ et $\frac{IC\times AH}2$ sont donc égales : chacune vaut $30:2=\res{15\ \mathrm{cm}^2}$.","Comparer bases et hauteurs.","assert Rational(30,2)==15",figure='rem-07'),
E('Utiliser la contraposée',r"On sait que : « Si un point appartient à la médiatrice de $[AB]$, alors il est équidistant de A et de B. » On mesure $PA=5$ cm et $PB=6$ cm. Que peut-on conclure pour P ? Quel énoncé utilise-t-on ?",r"P n’est pas équidistant de A et de B, car $5\ne6$. Par la $\res{\text{contraposée}}$ de l’énoncé : si un point n’est pas équidistant de A et de B, alors il n’appartient pas à la médiatrice de $[AB]$. Donc $\res{P\text{ n’est pas sur la médiatrice}}$.","Nier la conclusion pour nier l’hypothèse.","assert 5!=6",figure='rem-08'),
E('Une réciproque fausse',r"L’énoncé « Si un quadrilatère est un losange, alors ses diagonales sont perpendiculaires » est vrai. Écrire sa réciproque et montrer qu’elle est fausse.",r"Réciproque : « Si un quadrilatère a des diagonales perpendiculaires, alors c’est un losange. » Elle est $\res{\text{fausse}}$ : le cerf-volant EFGH de la figure corrigée a des diagonales perpendiculaires, mais $EF=EH\ne GF$ ; ce n’est pas un losange.","Chercher un quadrilatère qui vérifie la nouvelle hypothèse sans la conclusion.","A=(0,0);B=(2,-2);C=(7,0);D=(2,2); assert (C[0]-A[0])*(D[0]-B[0])+(C[1]-A[1])*(D[1]-B[1])==0 and (B[0]-A[0])**2+(B[1]-A[1])**2!=(C[0]-B[0])**2+(C[1]-B[1])**2",figure='rem-09'),
E('Le triangle isocèle',r"ABC est isocèle en A et I est le milieu de $[BC]$. Démontrer que A appartient à la médiatrice de $[BC]$. En déduire que $(AI)$ est à la fois la médiane et la hauteur issues de A.",r"$AB=AC$ : A est équidistant de B et C, donc il est sur la médiatrice de $[BC]$. Cette médiatrice passe aussi par I, milieu de $[BC]$ : c’est la droite $(AI)$. Ainsi $(AI)$ est la $\res{\text{médiane}}$ issue de A, et elle est perpendiculaire à $(BC)$ : c’est aussi la $\res{\text{hauteur}}$ issue de A.","Utiliser la réciproque de la propriété de la médiatrice.","A=(3,4);B=(0,0);C=(6,0);I=(3,0); assert (A[0]-B[0])**2+(A[1]-B[1])**2==(A[0]-C[0])**2+(A[1]-C[1])**2 and (A[0]-I[0])*(C[0]-B[0])+(A[1]-I[1])*(C[1]-B[1])==0",figure='rem-10'),
E('Le point commun des hauteurs',r"Dans le triangle ABC, les hauteurs issues de A et de B se coupent en H. Démontrer que $(CH)$ est perpendiculaire à $(AB)$. Si ABC est rectangle en C, où se trouve H ?",r"Les trois hauteurs d’un triangle sont concourantes : la hauteur issue de C passe donc par H, et cette hauteur est $(CH)$. Ainsi $\res{(CH)\perp(AB)}$. Si ABC est rectangle en C, $(CA)$ et $(CB)$ sont des hauteurs qui se coupent en C : $\res{H=C}$.","Utiliser la concourance des hauteurs.","A=(0,0);B=(7,0);C=(3,5); H=(3,Rational(12,5)); assert (H[0]-A[0])*(C[0]-B[0])+(H[1]-A[1])*(C[1]-B[1])==0 and (H[0]-B[0])*(C[0]-A[0])+(H[1]-B[1])*(C[1]-A[1])==0 and H[0]==C[0]",figure='rem-11'),
E('Raisonner par l’absurde',r"Démontrer par l’absurde qu’un triangle ne peut pas avoir deux angles droits.",r"Supposons qu’un triangle ABC ait deux angles droits, en B et en C. La somme $\widehat B+\widehat C$ vaudrait déjà $180^\circ$, et l’angle en A serait nul : impossible pour un triangle. On peut aussi voir que $(BA)$ et $(CA)$ seraient deux perpendiculaires à $(BC)$, donc parallèles, et ne pourraient pas se couper en A. $\res{\text{L’hypothèse est fausse.}}$","Supposer le contraire et chercher une contradiction.","assert 90+90==180",figure='rem-12'),
E('Trois maisons et un puits',r"Trois maisons A, B et C ne sont pas alignées. On veut creuser un puits à égale distance des trois maisons. Expliquer comment construire son emplacement O et justifier qu’il convient.",r"On trace les médiatrices de $[AB]$ et de $[BC]$ ; elles se coupent en O. O est sur la médiatrice de $[AB]$, donc $OA=OB$ ; il est sur celle de $[BC]$, donc $OB=OC$. Ainsi $\res{OA=OB=OC}$ : O est le centre du cercle circonscrit à ABC et il appartient aussi à la médiatrice de $[AC]$.","Enchaîner deux propriétés de la médiatrice.","A=(0,0);B=(6,0);C=(2,4); O=(3,1); d=lambda P:(P[0]-O[0])**2+(P[1]-O[1])**2; assert d(A)==d(B)==d(C)",figure='rem-13'),
E('Vrai ou faux ?',r"Dire si chaque énoncé est vrai ou faux et justifier."+Q(r"Si deux droites sont perpendiculaires à une même droite, alors elles sont parallèles.",r"Si un triangle a deux côtés de même longueur, alors ses trois angles sont égaux.",r"Si deux droites ne sont pas parallèles, alors elles ne sont pas perpendiculaires à une même droite."),r"a) $\res{\text{Vrai}}$ : les angles correspondants formés avec la droite commune sont droits, donc égaux ; les droites sont parallèles. b) $\res{\text{Faux}}$ : un triangle isocèle d’angles $74^\circ$, $53^\circ$ et $53^\circ$ est un contre-exemple. c) $\res{\text{Vrai}}$ : c’est la contraposée de l’énoncé a), qui est vrai.","Démontrer, réfuter ou reconnaître une contraposée.","assert 74+53+53==180 and 74!=53",figure='rem-14'),
E('Une médiane dans une médiane',r"Dans le triangle ABC, d’aire 36 cm$^2$, I est le milieu de $[BC]$ et J le milieu de $[AI]$. Démontrer que l’aire du triangle ABJ est le quart de celle de ABC, puis la calculer.",r"$[AI]$ est une médiane de ABC : l’aire de ABI vaut $\frac12\times36=18$ cm$^2$. Dans le triangle ABI, $[BJ]$ est une médiane car J est le milieu de $[AI]$ : l’aire de ABJ vaut $\frac12\times18=\res{9\ \mathrm{cm}^2}$, soit $\frac14$ de l’aire de ABC.","Utiliser deux fois la propriété de la médiane.","assert Rational(1,2)*Rational(1,2)*36==9",figure='rem-15')
],reperes=['Droites remarquables d’un triangle','Hypothèse, conclusion et réciproque','Contraposée, contre-exemple et absurde','Preuves avec des aires et des distances'],deco='raisonner')
